// src/hooks/UseWatchedFolders.js
import { useEffect, useMemo, useState } from 'react';
import {
  addWatchedFolder,
  deleteWatchedFolder,
  fetchWatchedFolders,
} from '../api/SettingApi';

const STORAGE_KEY = 'watchservice.watchedFolders';

function safeParseJson(raw) {
  try {
    const v = JSON.parse(raw);
    return v;
  } catch {
    return null;
  }
}

function deriveNameFromPath(path) {
  const segments = String(path || '').split(/[\\/]/).filter(Boolean);
  return segments[segments.length - 1] || path;
}

function normalizeFolders(list) {
  if (!Array.isArray(list)) return [];
  return list
    .filter(Boolean)
    .map((f) => ({
      id: f.id,
      name: f.name || deriveNameFromPath(f.path),
      path: f.path || '',
    }))
    .filter((f) => f.path);
}

/**
 * 감시 폴더 훅
 * - 우선: 백엔드 /settings/folders
 * - 실패: localStorage(STORAGE_KEY)
 */
export function useWatchedFolders() {
  const [folders, setFolders] = useState(() => {
    const raw = localStorage.getItem(STORAGE_KEY);
    const parsed = raw ? safeParseJson(raw) : null;
    return Array.isArray(parsed) ? normalizeFolders(parsed) : [];
  });

  const [backendAvailable, setBackendAvailable] = useState(false);

  // 최초 1회: 서버에서 가져오기 시도
  useEffect(() => {
    let mounted = true;

    (async () => {
      try {
        const list = await fetchWatchedFolders();
        const next = normalizeFolders(list);
        if (!mounted) return;

        setFolders(next);
        setBackendAvailable(true);

        // 서버 값도 캐시
        localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      } catch (e) {
        // 서버 없으면 로컬로만 동작
        setBackendAvailable(false);
      }
    })();

    return () => {
      mounted = false;
    };
  }, []);

  // 변경 시 로컬 캐시 갱신 (서버가 있든 없든)
  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(folders));
    } catch {
      // ignore
    }
  }, [folders]);

  const addFolderByPath = async (path) => {
    const p = String(path || '').trim();
    if (!p) return;

    // 중복 방지
    if (folders.some((f) => f.path === p)) return;

    const name = deriveNameFromPath(p);

    // 서버 우선
    if (backendAvailable) {
      try {
        const created = await addWatchedFolder({ name, path: p });
        const normalized = normalizeFolders([created])[0];
        if (normalized) {
          setFolders((prev) => [...prev, normalized]);
          return;
        }
      } catch (e) {
        // 서버 실패하면 로컬 fallback
      }
    }

    // 로컬 fallback
    setFolders((prev) => {
      const nextId = prev.length === 0 ? 1 : Math.max(...prev.map((x) => Number(x.id) || 0)) + 1;
      return [...prev, { id: nextId, name, path: p }];
    });
  };

  const promptAndAddFolder = async () => {
    const path = window.prompt(
      '감시할 폴더의 전체 경로를 입력하세요.\n예: /Users/you/Desktop/testwatch'
    );
    if (!path) return;
    await addFolderByPath(path);
  };

  const removeFolder = async (id) => {
    const targetId = id;

    if (backendAvailable) {
      try {
        await deleteWatchedFolder(targetId);
        setFolders((prev) => prev.filter((f) => f.id !== targetId));
        return;
      } catch (e) {
        // 서버 실패 → 로컬 fallback
      }
    }

    setFolders((prev) => prev.filter((f) => f.id !== targetId));
  };

  const primaryPath = useMemo(() => folders[0]?.path || '', [folders]);

  return {
    folders,
    setFolders,
    addFolderByPath,
    promptAndAddFolder,
    removeFolder,
    backendAvailable,
    primaryPath,
  };
}
